const fs = require('fs');
const path = require('path');

const dir = __dirname;
const manifest = 'backup-manifest.json';

const files = fs
  .readdirSync(dir, { withFileTypes: true })
  .filter((entry) => entry.isFile() && !entry.name.startsWith('.') && entry.name !== manifest)
  .map((entry) => entry.name)
  .sort();

fs.writeFileSync(path.join(dir, manifest), JSON.stringify({ files }, null, 2) + '\n');

